      SUBROUTINE PICKUP(I)CC     STORES BEAM MATRIX AT UPDATE FOR USE IN MISALIGNMENT CALCULATIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM8E.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'CC     LOCAL VARIABLESC      INTEGER         I, J, KC-----------------------------------------------------------------------------      LUP(I) = LC      IF (.NOT. RECENT) CALL BEAM      SPO(I) = SOFA      DO 5 J = 1, 6      COLD(I,J) = CEN(J)    5 CONTINUEC      IF (NORD2 .LT. 1) GO TO 100      DO 10 J = 1, 6      DO 10 K = 1, 6      SIOL(I,J,K) = SIT(J,K)   10 CONTINUEC      IF (RCP) THEN        DO 20 J = 1, 6        DO 20 K = 1, 6        RCO(I,J,K) = RC(J,K)   20   CONTINUE      ENDIFC   30 IF (I .EQ. 1) THEN        DO 40 J = 1, 6        DO 40 K = 1, 6        R2O(J,K) = RC2(J,K)   40   CONTINUE      ENDIFC      RCPO(I) = RCP      IF (I .EQ. 1) R2PO = R2P  100 RETURN      END